// Extensions conservant les essais de la première version.
state.wallet??={balance:120,transactions:[{id:'initial',title:'Dotation de découverte',amount:120,date:'2026-10-27',detail:'Crédit fictif initial'}],earned:[]};
state.gardenV2??={plants:[],observations:[],tasks:[],logs:[]};state.forum??={threads:[],replies:[],votes:[],saved:[]};save();
const nowDate=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'America/Martinique'});const displayDate=s=>s?new Date(s+'T12:00:00').toLocaleDateString('fr-FR',{day:'numeric',month:'short',year:'numeric'}):'Non renseigné';const liens=n=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(n)+' L';
routes.splice(5,0,['wallet','◈','Mon wallet']);
let selectedChannel='Tous',forumQuery='',gardenTab='suivi',sceneAngle=-32;
function residence3d(){return `<div class="scene3d" role="group" aria-label="Maquette 3D interactive de la résidence"><span class="scenehint">MAQUETTE 3D · EXPLORATION DU LIEU</span><div class="world3d" id="world3d"><div class="ground3d"><div class="path3d"></div><div class="object3d first selected" data-object="habitat"><div class="face back"></div><div class="face front"></div><div class="face side"></div><div class="face roof"></div></div><div class="object3d second" data-object="labo"><div class="face back"></div><div class="face front"></div><div class="face side"></div><div class="face roof"></div></div><div class="garden3d" data-object="jardin">${Array.from({length:6},()=>'<span class="sprout3d"></span>').join('')}</div><div class="tree3d" style="left:220px;top:18px"></div><div class="tree3d" style="left:245px;top:208px"></div></div></div></div><div class="scenecontrols"><label for="rotation3d">Faire pivoter le lieu<input type="range" id="rotation3d" min="-180" max="180" value="-32" oninput="rotateScene(this.value)"></label><button aria-pressed="true" onclick="selectObject('habitat',this)">Habitat</button><button aria-pressed="false" onclick="selectObject('jardin',this)">Potager</button><button aria-pressed="false" onclick="selectObject('labo',this)">Laboratoire</button></div><p id="objectdetail" class="sub" aria-live="polite">A03 · Container privé, terrasse et toiture solaire conceptuelle.</p><p class="smallnote">Objets volumétriques en CSS · vue conceptuelle, sans dimensions contractuelles.</p>`}
function rotateScene(v){sceneAngle=Number(v);const w=$('#world3d');if(w)w.style.transform=`translate(-50%,-50%) rotateX(58deg) rotateZ(${sceneAngle}deg)`}function selectObject(k,b){document.querySelectorAll('.scenecontrols button').forEach(x=>x.setAttribute('aria-pressed',x===b));document.querySelectorAll('[data-object]').forEach(x=>x.classList.toggle('selected',x.dataset.object===k));$('#objectdetail').textContent={habitat:'A03 · Container privé, terrasse et toiture solaire conceptuelle.',jardin:'Potager · Bacs cultivés et réseau d’arrosage conceptuel. Ouvrez « Mon jardin » pour saisir vos relevés.',labo:'Laboratoire · Container de transformation et distribution en circuit court.'}[k];rotateScene(k==='jardin'?-15:k==='labo'?145:-32);$('#rotation3d').value=sceneAngle}
const homeV1=home;home=function(){return homeV1()+`<section class="panel" style="margin-top:25px"><div class="paneltop"><h2>Votre résidence prend du relief.</h2><a class="textlink" href="#wallet">Découvrir le Lien ↗</a></div><div class="twocol"><div>${residence3d()}</div><div><div class="eyebrow">NOUVELLE EXPLORATION</div><h2 style="font-size:28px;margin:20px 0">Habiter, cultiver,<br>échanger autrement.</h2><p class="sub">Faites pivoter le lieu et explorez les objets. Retrouvez un journal de potager daté, des salons de discussion et une monnaie de démonstration.</p><div class="featureline"><span>◈</span><div><b>Votre wallet · ${liens(state.wallet.balance)}</b><p>Des unités fictives pour découvrir les échanges locaux.</p><a class="textlink" href="#wallet">Ouvrir mon wallet ↗</a></div></div><div class="featureline"><span>♧</span><div><b>Le potager, au jour le jour</b><p>Plantations, mesures manuelles, tâches et historique.</p><a class="textlink" href="#jardin">Suivre mes cultures ↗</a></div></div></div></div></section>`};views.accueil=home;
function coin(){return `<div class="coin-stage"><div class="coin3d" id="coin3d"><div class="coinedge"></div><div class="coinside coinfront">L</div><div class="coinside coinback">LE LIEN</div></div></div><button class="textlink" style="width:100%;color:inherit" onclick="document.getElementById('coin3d').classList.toggle('flipped')">Retourner la pièce 3D ↻</button>`}
function wallet(){return heading('Le Lien. Une valeur qui circule ici.','Une proposition de monnaie locale imaginaire pour explorer les échanges du collectif.',`<button class="btn light" onclick="walletStory()">▷ Présenter le wallet</button>`)+`<div class="twocol"><div><section class="walletcard"><div class="eyebrow">Domaine · WALLET DE DÉMONSTRATION</div><div class="wallet3d"><div><div class="walletbalance">${new Intl.NumberFormat('fr-FR').format(state.wallet.balance)} <small>Liens</small></div><p style="color:#c4d4b9;font-size:12px;line-height:1.8">Votre réserve d’unités pour les échanges imaginés au sein de la résidence.</p></div><div>${coin()}</div></div><div class="walletbottom"><span>Alex · A03<br><small>Compte fictif local</small></span><span>◈ &nbsp; LE LIEN</span></div></section><div class="walletactions"><button class="btn" onclick="transferForm()">↗ Envoyer des Liens</button><button class="btn light" onclick="receiveWallet()">↙ Recevoir</button><button class="btn light" onclick="walletPay()">♧ Payer un panier</button></div><section class="panel"><div class="paneltop"><h2>Les mouvements du wallet</h2><span class="mini">Registre fictif</span></div>${state.wallet.transactions.map(t=>`<div class="tx"><span class="txicon">${t.amount>0?'↙':'↗'}</span><div class="txbody"><b>${esc(t.title)}</b><p>${displayDate(t.date)} · ${esc(t.detail)}</p></div><span class="amount ${t.amount>0?'plus':''}">${t.amount>0?'+':''}${liens(t.amount)}</span></div>`).join('')}</section></div><div><section class="panel"><div class="eyebrow">LE CONCEPT</div><h2 style="font-size:25px;margin:18px 0">Garder les échanges<br>près de chez nous.</h2><p class="sub">Le Lien imagine une boucle entre les habitants, les producteurs et les services partagés. Il permet de présenter un usage avant de décider d’un système réel.</p><div class="featureline"><span>01</span><div><b>Participer</b><p>Une contribution collective peut illustrer l’attribution de Liens.</p></div></div><div class="featureline"><span>02</span><div><b>Échanger</b><p>Envoyer des unités à un voisin fictif ou simuler un panier chez un producteur.</p></div></div><div class="featureline"><span>03</span><div><b>Comprendre</b><p>Chaque mouvement apparaît dans l’historique du wallet.</p></div></div><div class="notice">Le Lien n’existe pas en dehors de cette maquette. Aucune valeur en euros, conversion, recharge bancaire, crypto ou promesse de gain. Le solde est modifiable dans ce navigateur.</div></section><section class="panel"><h2>Découvrir par la participation</h2><p class="smallnote">Scénarios fictifs, activables une seule fois par essai. Aucune participation réelle n’est vérifiée.</p>${[['atelier',10,'Participation à un atelier'],['compost',5,'Coup de main au compost']].map(x=>`<div class="event"><div><h3>${x[2]}</h3><p>Scénario · +${x[1]} Liens fictifs</p></div><button class="textlink" ${state.wallet.earned.includes(x[0])?'disabled':''} onclick="earnLien('${x[0]}',${x[1]})">${state.wallet.earned.includes(x[0])?'Déjà testé':'Simuler ↗'}</button></div>`).join('')}</section></div></div>`}views.wallet=wallet;
function walletStory(){modal(`<div class="eyebrow">UNE MONNAIE À IMAGINER ENSEMBLE</div><h2 style="margin-top:20px">Le Lien : de la participation au circuit local.</h2><p>① Une dotation fictive permet de découvrir le wallet.<br>② Un échange débite le solde et laisse une trace datée.<br>③ Un producteur fictif peut accepter un panier simulé en Liens.</p><p>Avant toute version réelle, il faudra définir collectivement les règles d’émission, de gouvernance et d’usage, puis faire étudier le montage adapté.</p><button class="btn" onclick="document.getElementById('modal').close();openPresentation()">Voir la présentation complète ↗</button>`)}function walletTx(title,amount,detail){state.wallet.balance=Math.round((state.wallet.balance+amount)*100)/100;state.wallet.transactions.unshift({id:'tx'+Date.now(),title,amount,date:nowDate(),detail});save()}
function transferForm(){modal(`<h2>Envoyer des Liens fictifs</h2><p>Solde disponible : ${liens(state.wallet.balance)}. Aucun destinataire réel ne reçoit de fonds.</p><form onsubmit="event.preventDefault();confirmTransfer(this)"><label for="recipient">Destinataire de démonstration</label><select id="recipient" name="recipient"><option>Camille · Jardin partagé</option><option>Noé · Entraide</option><option>Collectif · Maison commune</option></select><label for="amount">Montant en Liens</label><input id="amount" name="amount" type="number" required min="1" max="${state.wallet.balance}" step="1" value="10"><label for="reason">Motif</label><input id="reason" name="reason" maxlength="100" required value="Échange local de démonstration"><p id="wallet-error" role="alert"></p><button class="btn" style="margin-top:15px">Confirmer le transfert fictif</button></form>`)}function confirmTransfer(f){let n=Number(f.amount.value);if(!Number.isFinite(n)||n<=0||n>state.wallet.balance){$('#wallet-error').textContent='Montant invalide ou solde insuffisant.';return}walletTx('À '+f.recipient.value,-n,f.reason.value);$('#modal').close();render();toast('Transfert fictif enregistré. Aucun fonds transféré.')}function receiveWallet(){modal(`<h2>Recevoir dans la démo</h2><p>Identifiant de présentation : <b>LIEN-A03-DEMO</b></p><div class="notice">Cet identifiant n’est pas une adresse de paiement. Aucun transfert entre appareils n’est possible dans cette version.</div><p>Pour tester un crédit, utilisez un scénario de participation dans le wallet.</p>`)}function earnLien(id,n){if(state.wallet.earned.includes(id))return;state.wallet.earned.push(id);walletTx('Participation fictive : '+(id==='atelier'?'atelier':'compost'),n,'Scénario de découverte');render();toast('+'+n+' Liens fictifs crédités.')}
function walletPay(){if(!Object.keys(state.cart).length){modal(`<h2>Votre panier est vide.</h2><p>Choisissez d’abord des produits dans le marché. Le parcours en Liens utilise un tarif fictif d’une unité par point de prix affiché, sans conversion en euros.</p><button class="btn" onclick="document.getElementById('modal').close();location.hash='#producteurs'">Explorer le marché</button>`);return}const n=total();modal(`<h2>Payer en Liens fictifs</h2><p>Panier de démonstration : <b>${liens(n)}</b>.<br>Solde : ${liens(state.wallet.balance)}.</p><p class="smallnote">Tarif illustratif propre à la maquette, sans valeur convertible en euros.</p>${n>state.wallet.balance?'<div class="notice">Votre solde fictif est insuffisant.</div>':`<button class="btn" onclick="confirmWalletPay()">Confirmer le paiement fictif</button>`}`)}function confirmWalletPay(){let n=total();if(n<=0||n>state.wallet.balance)return;walletTx('Panier au marché local',-n,'Paiement fictif · aucune vente réelle');state.orders.unshift({id:'LIEN-'+String(Date.now()).slice(-5),total:n,count:Object.values(state.cart).reduce((a,b)=>a+b,0),slot:'Jeudi · 17 h – 18 h',currency:'L'});state.cart={};save();$('#modal').close();render();toast('Panier fictif réglé en Liens. Historique mis à jour.')}
const cartV1=cartModal;cartModal=function(){cartV1();if(Object.keys(state.cart).length){$('#modalbody').insertAdjacentHTML('beforeend','<button class="btn light" style="margin-top:12px;width:100%" onclick="document.getElementById(\'modal\').close();walletPay()">◈ Tester le paiement en Liens</button>')}};
const marketV1=market;market=function(){return marketV1().replace(/(LIEN-\d+ · )([\d\s  ,.]+)€/g,'$1$2L')};views.producteurs=market;
function gardenV2(){const g=state.gardenV2;const last=g.observations[0];return heading('Le potager, au jour le jour.','Un vrai carnet de saisie pour vos cultures. Les capteurs de la maquette restent simulés.',`<button class="btn" onclick="plantForm()">＋ Ajouter une culture</button>`)+`<div class="summarystrip"><span><b>${g.plants.length}</b> cultures enregistrées</span><span><b>${g.tasks.filter(t=>!t.done).length}</b> tâches à faire</span><span><b>${state.harvest.reduce((a,h)=>a+Number(h.kg),0).toFixed(1)} kg</b> récoltés dans le carnet</span><span>Dernier relevé : <b>${last?displayDate(last.date):'aucun'}</b></span></div><div class="segmented" aria-label="Vues du potager">${[['suivi','Mes cultures'],['mesures','Relevés & historique'],['taches','Tâches & journal'],['simulation','Capteurs simulés']].map(x=>`<button aria-pressed="${gardenTab===x[0]}" onclick="gardenTab='${x[0]}';render()">${x[1]}</button>`).join('')}</div>${gardenTab==='simulation'?jardinV1().replace(heading('Cultiver un peu. Partager beaucoup.','Vos parcelles, les ressources en eau et les récoltes du collectif.'),''):gardenTab==='mesures'?gardenMeasures():gardenTab==='taches'?gardenTasks():gardenCrops()}`}
const jardinV1=jardin;views.jardin=gardenV2;
function plantForm(){modal(`<h2>Nouvelle culture</h2><p>Enregistrez une plantation réelle ou un exemple. Vos saisies restent sur cet appareil.</p><form onsubmit="event.preventDefault();createPlant(this)"><div class="formrow"><div><label for="plantname">Culture / variété</label><input name="plantname" id="plantname" required maxlength="80" placeholder="Ex. : tomates anciennes"></div><div><label for="plot">Parcelle</label><input id="plot" name="plot" required maxlength="40" value="A03"></div></div><div class="formrow"><div><label for="sowdate">Date de plantation</label><input id="sowdate" name="sowdate" type="date" required value="${nowDate()}"></div><div><label for="count">Nombre de plants</label><input id="count" name="count" type="number" min="1" max="10000" required value="6"></div></div><label for="harvestdate">Récolte prévue (facultatif, votre estimation)</label><input id="harvestdate" name="harvestdate" type="date"><label for="planttype">Nature de cette saisie</label><select id="planttype" name="planttype"><option>Exemple fictif</option><option>Ma saisie personnelle</option></select><button class="btn" style="margin-top:20px">Enregistrer la culture</button></form>`)}function createPlant(f){let g=state.gardenV2;const p={id:'crop'+Date.now(),name:f.plantname.value,plot:f.plot.value,date:f.sowdate.value,count:Number(f.count.value),harvest:f.harvestdate.value,source:f.planttype.value,stage:'Plantation'};if(p.harvest&&p.harvest<p.date){toast('La récolte prévue doit suivre la plantation.');return}g.plants.push(p);gardenLog('Plantation',p.name+' · '+p.count+' plants · parcelle '+p.plot,p.date);save();$('#modal').close();gardenTab='suivi';render();toast('Culture ajoutée à votre carnet.')}
function gardenCrops(){const g=state.gardenV2;return `${!g.plants.length?`<section class="panel"><div class="twocol"><div><div class="eyebrow">VOTRE SUIVI COMMENCE ICI</div><h2 style="font-size:28px;margin:20px 0">Chaque culture<br>a son histoire.</h2><p class="sub">Ajoutez une plantation, définissez une date, puis suivez son stade, vos gestes et vos récoltes. Aucune donnée de capteur n’est inventée dans votre carnet.</p><button class="btn" style="margin-top:22px" onclick="plantForm()">Ajouter ma première culture</button></div><div>${residence3d()}</div></div></section>`:`<div class="grid3">${g.plants.map(p=>`<section class="trackcard"><div class="cropvisual">${/tomate/i.test(p.name)?'🍅':/courge/i.test(p.name)?'🎃':'🌱'}<span class="mini">${esc(p.source)}</span></div><h3 style="margin-top:18px">${esc(p.name)}</h3><div class="cropmeta"><span>Parcelle ${esc(p.plot)}</span><span>${p.count} plants</span></div><p class="sub">Plantation : ${displayDate(p.date)}<br>Récolte estimée : ${p.harvest?displayDate(p.harvest):'à préciser'}</p><label for="stage-${p.id}">Stade observé manuellement</label><select id="stage-${p.id}" onchange="plantStage('${p.id}',this.value)">${['Plantation','Croissance','Floraison','Fructification','Récolte','Terminée'].map(s=>`<option ${p.stage===s?'selected':''}>${s}</option>`).join('')}</select><button class="textlink" style="margin-top:15px" onclick="harvestForm('${p.id}')">＋ Enregistrer une récolte</button></section>`).join('')}</div>`}<section class="panel" style="margin-top:20px"><div class="paneltop"><h2>Le carnet des récoltes</h2><button class="textlink" onclick="harvestForm('')">Ajouter une récolte ↗</button></div>${state.harvest.length?state.harvest.map(h=>`<div class="event"><span class="emojibadge">♧</span><div><h3>${esc(h.crop)} · ${h.kg} kg</h3><p>${h.date?displayDate(h.date):'Ancienne saisie sans date'} · ${esc(h.note||'Saisie locale')}</p></div></div>`).join(''):'<p class="smallnote">Aucune récolte saisie. Les récoltes de la première version sont conservées.</p>'}</section>`}
function plantStage(id,v){let p=state.gardenV2.plants.find(p=>p.id===id);p.stage=v;gardenLog('Évolution de culture',p.name+' : '+v);save();toast('Stade mis à jour dans le journal.')}function gardenLog(type,text,date=nowDate()){state.gardenV2.logs.unshift({id:'log'+Date.now()+Math.random(),type,text,date})}function harvestForm(id){let p=state.gardenV2.plants.find(p=>p.id===id);modal(`<h2>Noter une récolte</h2><form onsubmit="event.preventDefault();newHarvest(this)"><label for="hcrop">Culture</label><input name="hcrop" id="hcrop" required maxlength="80" value="${esc(p?.name||'')}"><div class="formrow"><div><label for="hkg">Quantité (kg)</label><input name="hkg" id="hkg" type="number" min="0.01" max="10000" step="0.01" required value="1"></div><div><label for="hdate">Date</label><input name="hdate" id="hdate" type="date" required value="${nowDate()}"></div></div><label for="hnote">Observation</label><input name="hnote" id="hnote" maxlength="200" placeholder="Qualité, partage, destination…"><button class="btn" style="margin-top:20px">Enregistrer la récolte</button></form>`)}function newHarvest(f){state.harvest.unshift({crop:f.hcrop.value,kg:Number(f.hkg.value),date:f.hdate.value,note:f.hnote.value});gardenLog('Récolte',f.hcrop.value+' · '+f.hkg.value+' kg',f.hdate.value);save();$('#modal').close();render();toast('Récolte datée ajoutée.')}
function gardenMeasures(){const g=state.gardenV2,o=g.observations[0];let recent=[...g.observations].sort((a,b)=>a.date.localeCompare(b.date)).slice(-7);return `<div class="twocol"><section class="panel"><div class="paneltop"><h2>Relevés manuels</h2><span class="mini">Aucun capteur connecté</span></div><div class="measuregrid">${[['Humidité sol',o?.humidity,'%'],['Température',o?.temp,'°C'],['Eau apportée',o?.water,'L'],['pH',o?.ph,'']].map(m=>`<div class="measure"><small>${m[0]}</small><b>${m[1]===undefined||m[1]===''?'—':esc(m[1])} <small>${m[1]===undefined||m[1]===''?'':m[2]}</small></b></div>`).join('')}</div><p class="smallnote">${o?'Dernière saisie : '+displayDate(o.date)+' · parcelle '+esc(o.plot):'Aucune mesure saisie. Les indicateurs restent vides tant que vous ne les renseignez pas.'}</p><h3 style="margin-top:25px">Historique d’humidité saisi</h3>${recent.length?`<div class="trend" role="img" aria-label="Humidité saisie pour les derniers relevés : ${recent.map(r=>r.humidity+' pour cent').join(', ')}">${recent.map(r=>`<div class="bar" style="height:${r.humidity}%"><span>${r.humidity}%</span></div>`).join('')}</div><p class="chartcaption">${displayDate(recent[0].date)} → ${displayDate(recent.at(-1).date)} · ${recent.length} relevé(s) · parcelles saisies confondues</p>`:'<p class="smallnote">Votre historique apparaîtra après le premier relevé.</p>'}</section><section class="panel"><h2>Ajouter un relevé</h2><form onsubmit="event.preventDefault();addObservation(this)"><div class="formrow"><div><label for="odate">Date du relevé</label><input type="date" required name="date" id="odate" value="${nowDate()}"></div><div><label for="oplot">Parcelle</label><input name="plot" id="oplot" maxlength="40" required value="A03"></div></div><div class="formrow"><div><label for="ohumidity">Humidité sol (%)</label><input name="humidity" id="ohumidity" type="number" min="0" max="100" required></div><div><label for="otemp">Température (°C, facultatif)</label><input name="temp" id="otemp" type="number" min="-30" max="70" step="0.1"></div></div><div class="formrow"><div><label for="owater">Eau apportée (L, facultatif)</label><input name="water" id="owater" type="number" min="0" max="10000" step="0.1"></div><div><label for="oph">pH (facultatif)</label><input name="ph" id="oph" type="number" min="0" max="14" step="0.1"></div></div><label for="onote">État des plantes / observation</label><textarea name="note" id="onote" maxlength="500" placeholder="Feuillage, ravageurs observés, croissance…"></textarea><button class="btn" style="margin-top:15px">Enregistrer le relevé</button></form></section></div><section class="panel"><h2>Tous mes relevés</h2>${g.observations.map(r=>`<div class="journalrow"><b>${displayDate(r.date)} · ${esc(r.plot)}</b><p>Humidité : ${r.humidity} %${r.temp!==''?' · '+r.temp+' °C':''}${r.water!==''?' · eau '+r.water+' L':''}${r.ph!==''?' · pH '+r.ph:''}<br>${esc(r.note)}</p><small>Saisie manuelle · non vérifiée par un capteur</small></div>`).join('')||'<p class="smallnote">Aucun relevé.</p>'}</section>`}function addObservation(f){const r={date:f.date.value,plot:f.plot.value,humidity:Number(f.humidity.value),temp:f.temp.value,water:f.water.value,ph:f.ph.value,note:f.note.value};state.gardenV2.observations.unshift(r);state.gardenV2.observations.sort((a,b)=>b.date.localeCompare(a.date));gardenLog('Relevé manuel','Parcelle '+r.plot+' · humidité '+r.humidity+' %',r.date);save();render();toast('Relevé ajouté. Vos mesures et leur historique sont conservés localement.')}
function gardenTasks(){let g=state.gardenV2;return `<div class="twocol"><section class="panel"><h2>Mes gestes à planifier</h2>${g.tasks.map(t=>`<div class="taskrow ${t.done?'done':''}"><label><input type="checkbox" ${t.done?'checked':''} onchange="completeTask('${t.id}',this.checked)"><span>${esc(t.name)}<small>${displayDate(t.date)} · parcelle ${esc(t.plot)}</small></span></label></div>`).join('')||'<p class="smallnote">Ajoutez vos tâches : semer, observer, arroser, pailler, récolter… Les dates sont choisies par vous.</p>'}<form class="taskform" onsubmit="event.preventDefault();addTask(this)"><label for="taskname">Tâche</label><input name="taskname" id="taskname" required maxlength="100" placeholder="Ex. : observer le feuillage"><div class="formrow"><div><label for="taskdate">Date prévue</label><input name="taskdate" id="taskdate" type="date" required value="${nowDate()}"></div><div><label for="taskplot">Parcelle</label><input name="taskplot" id="taskplot" required maxlength="40" value="A03"></div></div><button class="btn" style="margin-top:15px">Ajouter la tâche</button></form><p class="smallnote">Pas de notification automatique dans cette version.</p></section><section class="panel"><h2>Journal des interventions</h2><form onsubmit="event.preventDefault();addGardenNote(this)"><label for="gardennote">Noter un geste ou une observation</label><textarea id="gardennote" name="note" required maxlength="500"></textarea><button class="btn light" style="margin:12px 0 25px">Ajouter au journal</button></form>${g.logs.map(l=>`<div class="journalrow"><b>${esc(l.type)}</b><p>${esc(l.text)}</p><small>${displayDate(l.date)}</small></div>`).join('')||'<p class="smallnote">Votre journal se complète au fil de vos saisies.</p>'}</section></div>`}function addTask(f){state.gardenV2.tasks.push({id:'task'+Date.now(),name:f.taskname.value,date:f.taskdate.value,plot:f.taskplot.value,done:false});save();render();toast('Tâche ajoutée.')}function completeTask(id,v){let t=state.gardenV2.tasks.find(t=>t.id===id);t.done=v;gardenLog(v?'Tâche terminée':'Tâche rouverte',t.name+' · '+t.plot);save();render()}function addGardenNote(f){gardenLog('Note personnelle',f.note.value);save();render();toast('Note ajoutée au journal.')}
const channels=['Tous','Annonces','Potager','Entraide','Producteurs','Idées & décisions'];const forumSeeds=[{id:'s1',channel:'Potager',title:'Samedi au potager : qui participe à la récolte ?',text:'Les tomates de la parcelle commune arrivent à maturité dans notre scénario. Proposons un rendez-vous, puis notons ensemble les quantités récoltées.',author:'Camille',initial:'CM',date:'2026-10-27',pinned:false},{id:'s2',channel:'Annonces',title:'Les paniers du jeudi : organisons le retrait',text:'Le point de retrait fictif sera ouvert entre 17 h et 19 h. Le salon permet de poser les questions liées à la distribution et de coordonner les bénévoles.',author:'Le collectif',initial:'CO',date:'2026-10-27',pinned:true},{id:'s3',channel:'Entraide',title:'Une perceuse disponible ce week-end',text:'Je propose une perceuse à partager. Pour essayer le parcours, réservez-la dans les ressources communes. Aucun prêt réel n’est organisé ici.',author:'Noé',initial:'ND',date:'2026-10-26',pinned:false},{id:'s4',channel:'Idées & décisions',title:'Que pourrait permettre le Lien dans notre résidence ?',text:'Paniers, ateliers ou prêts de matériel : quels usages seraient utiles ? Cette discussion porte sur un concept fictif, sans engagement financier.',author:'Alex',initial:'AL',date:'2026-10-27',pinned:false},{id:'s5',channel:'Producteurs',title:'Valoriser les surplus avec le laboratoire',text:'Imaginons une collecte hebdomadaire et un suivi des lots. Quelles informations partager entre producteurs et cuisine pour préparer le retrait ?',author:'Le Labo',initial:'LA',date:'2026-10-26',pinned:false}];
function allThreads(){return [...state.forum.threads,...forumSeeds,...state.posts.map(p=>({id:p.id,channel:'Entraide',title:'Message conservé de la première version',text:p.text,author:p.name,initial:p.initial,date:'',pinned:false}))]}
function forumV2(){let threads=allThreads().filter(t=>(selectedChannel==='Tous'||t.channel===selectedChannel)&&(!forumQuery||(t.title+' '+t.text+' '+t.author).toLowerCase().includes(forumQuery.toLowerCase())));return heading('Un espace pour faire collectif.','Des salons, des sujets et des réponses pour organiser la vie commune.',`<button class="btn" onclick="newThreadForm()">＋ Nouvelle discussion</button>`)+`<div class="notice">Espace de démonstration : les messages et réponses restent sur cet appareil. Il n’y a pas encore de discussion en temps réel entre habitants.</div><div class="channelbar" aria-label="Salons de discussion">${channels.map(c=>`<button aria-pressed="${selectedChannel===c}" onclick="selectedChannel='${c}';render()">${c==='Tous'?'◎':'#'} ${c}</button>`).join('')}</div><div class="twocol"><div><section class="panel"><form class="threadsearch" onsubmit="event.preventDefault();forumQuery=this.query.value;render()"><div><label for="threadquery">Rechercher dans les discussions</label><input type="search" name="query" id="threadquery" value="${esc(forumQuery)}" placeholder="Sujet, message ou auteur…"></div><button class="btn light">Rechercher</button>${forumQuery?'<button type="button" class="textlink" onclick="forumQuery=\'\';render()">Effacer</button>':''}</form></section><p class="smallnote">${threads.length} sujet(s) · ${selectedChannel}</p>${threads.map(t=>threadCard(t)).join('')||'<section class="panel"><p>Aucune discussion pour cette recherche.</p></section>'}</div><div><section class="panel"><h2>Repères du collectif</h2><p class="sub" style="margin-top:15px">Un sujet par discussion, des réponses dans son fil et des annonces faciles à retrouver.</p><div class="featureline"><span>①</span><div><b>Bien choisir son salon</b><p>Potager, producteurs, entraide ou idées communes.</p></div></div><div class="featureline"><span>②</span><div><b>Échanger avec respect</b><p>Décrire un besoin concret, éviter les informations privées et préserver le calme des échanges.</p></div></div><div class="featureline"><span>③</span><div><b>Passer à l’action</b><p>Réserver un espace ou noter une tâche dans le potager.</p></div></div></section><section class="panel"><h2>Agenda & ressources</h2>${event('SAM','31','Atelier potager','10 h · Jardin partagé','atelier')}${event('MAR','03','Conseil des habitants','18 h · Maison commune','conseil')}<div style="margin-top:20px">${['Salle commune','Vélo cargo','Perceuse'].map(r=>`<div class="event"><div><h3>${r}</h3><p>Ressource fictive</p></div><button class="textlink" onclick="reserve('${r}')">Réserver ↗</button></div>`).join('')}</div></section><section class="panel"><h2>Mes réservations</h2>${state.bookings.map(b=>`<div class="event"><div><h3>${esc(b.name)}</h3><p>${esc(b.slot)}</p></div><button class="textlink" onclick="cancelBooking('${b.id}')">Annuler</button></div>`).join('')||'<p class="smallnote">Aucune réservation.</p>'}</section></div></div>`}views.communaute=forumV2;
function threadCard(t){const replies=state.forum.replies.filter(r=>r.thread===t.id);return `<article class="thread"><div class="posthead"><span class="avatar">${esc(t.initial)}</span><div>${esc(t.author)}<small>${t.date?displayDate(t.date):'Ancienne saisie'} · # ${esc(t.channel)}</small></div>${t.pinned?'<span class="mini" style="margin-left:auto">Annonce repère</span>':''}</div><h3>${esc(t.title)}</h3><p>${esc(t.text)}</p><div class="postactions"><button aria-pressed="${state.forum.votes.includes(t.id)}" onclick="voteThread('${t.id}')">${state.forum.votes.includes(t.id)?'♥ Utile':'♡ Utile'}</button><button onclick="openThread('${t.id}')">↳ ${replies.length} réponse(s)</button><button aria-pressed="${state.forum.saved.includes(t.id)}" onclick="saveThread('${t.id}')">${state.forum.saved.includes(t.id)?'✓ Suivi':'＋ Suivre'}</button><button class="textlink" onclick="reportThread('${t.id}')">Signaler</button></div>${replies.slice(-2).map(r=>`<div class="threadreply"><b>Alex</b><p>${esc(r.text)}</p><small>${displayDate(r.date)} · réponse locale</small></div>`).join('')}</article>`}function newThreadForm(){modal(`<h2>Ouvrir une discussion</h2><p>Le sujet reste dans votre navigateur de démonstration.</p><form onsubmit="event.preventDefault();createThread(this)"><label for="channel">Salon</label><select id="channel" name="channel">${channels.slice(1).map(c=>`<option ${c===selectedChannel?'selected':''}>${c}</option>`).join('')}</select><label for="threadtitle">Titre du sujet</label><input id="threadtitle" name="threadtitle" required maxlength="120" placeholder="Quel sujet voulez-vous partager ?"><label for="threadtext">Message</label><textarea id="threadtext" name="threadtext" required maxlength="2000"></textarea><button class="btn" style="margin-top:20px">Publier dans la démo</button></form>`)}function createThread(f){let title=f.threadtitle.value.trim(),text=f.threadtext.value.trim();if(!title||!text){toast('Renseignez un titre et un message.');return}state.forum.threads.unshift({id:'thread'+Date.now(),channel:f.channel.value,title,text,author:'Alex',initial:'AL',date:nowDate()});selectedChannel=f.channel.value;forumQuery='';save();$('#modal').close();render();toast('Discussion créée localement.')}
function openThread(id){const t=allThreads().find(t=>t.id===id);modal(`<div class="eyebrow"># ${esc(t.channel)}</div><h2 style="margin-top:18px">${esc(t.title)}</h2><p>${esc(t.text)}</p>${state.forum.replies.filter(r=>r.thread===id).map(r=>`<div class="threadreply"><b>Alex</b><p>${esc(r.text)}</p><small>${displayDate(r.date)} · réponse locale</small></div>`).join('')}<form onsubmit="event.preventDefault();threadReply('${id}',this)"><label for="threadreply">Votre réponse</label><textarea id="threadreply" name="reply" required maxlength="1500" placeholder="Répondre à ce sujet…"></textarea><button class="btn" style="margin-top:15px">Ajouter la réponse locale</button></form>`)}function threadReply(id,f){if(!f.reply.value.trim())return;state.forum.replies.push({thread:id,text:f.reply.value.trim(),date:nowDate(),id:'reply'+Date.now()});save();$('#modal').close();render();toast('Réponse ajoutée au fil du sujet.')}function voteThread(id){state.forum.votes=state.forum.votes.includes(id)?state.forum.votes.filter(x=>x!==id):[...state.forum.votes,id];save();render()}function saveThread(id){state.forum.saved=state.forum.saved.includes(id)?state.forum.saved.filter(x=>x!==id):[...state.forum.saved,id];save();render();toast(state.forum.saved.includes(id)?'Sujet suivi localement. Aucune alerte automatique.':'Sujet retiré de votre suivi.')}function reportThread(id){modal(`<h2>Signaler un sujet</h2><p>Un signalement peut être noté localement pour tester ce parcours. Aucun modérateur réel ne le reçoit.</p><form onsubmit="event.preventDefault();localReport('${id}',this)"><label for="reportreason">Motif</label><select id="reportreason" name="reason"><option>Information privée</option><option>Propos inappropriés</option><option>Contenu hors sujet</option></select><button class="btn" style="margin-top:20px">Enregistrer le signalement de démo</button></form>`)}function localReport(id,f){state.checks.push({type:'report',thread:id,text:f.reason.value});save();$('#modal').close();toast('Signalement local enregistré. Aucun modérateur contacté.')}
slides.splice(4,0,{k:'05 · LE WALLET',title:'Le Lien.<br>Une monnaie locale à imaginer.',text:'Une proposition fictive pour explorer les échanges entre habitants, producteurs et services du collectif. Aucun euro, aucune conversion et aucune valeur financière réelle.',cards:[['Un wallet lisible','Un solde fictif et un historique de chaque mouvement.'],['Des usages à discuter','Panier local, atelier ou contribution au lieu de vie.'],['Une gouvernance à définir','Règles collectives à étudier avant toute version réelle.']]},{k:'06 · LE SUIVI DU POTAGER',title:'Observer. Noter.<br>Comprendre ce qui pousse.',text:'Un carnet daté pour les plantations, les relevés manuels, les tâches et les récoltes. Vos mesures sont distinguées des indicateurs simulés.',cards:[['Les cultures','Variété, parcelle, date et stade observé.'],['Les relevés','Humidité, température, eau et pH renseignés manuellement.'],['Le journal','Interventions et récoltes conservées dans ce navigateur.']]},{k:'07 · LE COLLECTIF',title:'Des voisins.<br>Des sujets qui avancent.',text:'Des salons organisés et des réponses par sujet pour coordonner le quotidien sans perdre les échanges.',cards:[['Discuter','Annonces, potager, producteurs, entraide et décisions.'],['Coordonner','Réserver un espace et préparer un rendez-vous commun.'],['Explorer en 3D','Faire pivoter une maquette de la résidence et retourner la pièce du Lien.']]});slides.forEach((s,i)=>s.k=String(i+1).padStart(2,'0')+' · '+s.k.split(' · ').slice(1).join(' · '));
// Le dernier écran conserve l’accès direct à l’application quel que soit le nombre de diapositives.
const slideV1=renderSlide;renderSlide=function(){slideV1();const extra=$('#slide').querySelector('.over>.btn');if(extra)extra.remove();if(slideIndex===slides.length-1)$('#slide .over').insertAdjacentHTML('beforeend','<button class="btn" style="margin-top:15px" onclick="document.getElementById(\'deck\').close();location.hash=\'#wallet\'">Essayer le wallet ↗</button>')};
const projetV1=projet;views.projet=function(){return projetV1()+`<section class="panel"><h2>La résidence en trois dimensions</h2><p class="sub" style="margin:15px 0">Explorez le volume des containers et des bacs de culture. Vue conceptuelle, sans relevé d’architecte.</p>${residence3d()}</section>`};
const resetV1=resetDemo;resetDemo=function(){resetV1();state.wallet={balance:120,transactions:[{id:'initial',title:'Dotation de découverte',amount:120,date:nowDate(),detail:'Crédit fictif initial'}],earned:[]};state.gardenV2={plants:[],observations:[],tasks:[],logs:[]};state.forum={threads:[],replies:[],votes:[],saved:[]};save();render()};render();
